import{_ as a,o as i,c as s,a3 as o}from"./chunks/framework.1Y430-yj.js";const f=JSON.parse('{"title":"Changes Caused by Going Offline","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"离线变化问题","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=GjnzRv6BmgC2eu1H5cGJWs","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-GjnzRv6BmgC2eu1H5cGJWs.md","filePath":"logistics/src/page-GjnzRv6BmgC2eu1H5cGJWs.md","lastUpdated":null}'),n={name:"logistics/src/page-GjnzRv6BmgC2eu1H5cGJWs.md"};function t(r,e,l,c,d,p){return i(),s("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="离线变化问题" aria-hidden="true"></span><h1 id="changes-caused-by-going-offline" tabindex="-1">Changes Caused by Going Offline <a class="header-anchor" href="#changes-caused-by-going-offline" aria-label="Permalink to &quot;Changes Caused by Going Offline&quot;">​</a></h1><blockquote><p>Source page ID: <code>GjnzRv6BmgC2eu1H5cGJWs</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=GjnzRv6BmgC2eu1H5cGJWs" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Known problems triggered by going offline:</p><p><span id="source-block-WMbSyPWYK7nw7P4uE58IPH"></span></p><span class="logistics-source-anchor" id="准入口降速" aria-hidden="true"></span><h4 id="control-port-slowdown" tabindex="-1">Control-Port Slowdown <a class="header-anchor" href="#control-port-slowdown" aria-label="Permalink to &quot;Control-Port Slowdown&quot;">​</a></h4><p>The current view is that the lower the rate limit, the less it is affected by going offline. Differences in rate or instantaneous priority between Control Ports and other logistics components can be used to measure time spent offline, or to build structures with extremely low rate limits using few components.</p><p><span id="source-block-WHHUYSpa6DPnVeGB3liEWV"></span></p><span class="logistics-source-anchor" id="优先汇入优先级变化" aria-hidden="true"></span><h4 id="changes-in-merge-priority" tabindex="-1">Changes in Merge Priority <a class="header-anchor" href="#changes-in-merge-priority" aria-label="Permalink to &quot;Changes in Merge Priority&quot;">​</a></h4><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-97d6b4b2ee7eb1df.q90-6c395936ede055dd.webp" alt="Changes Caused by Going Offline"></p><p>The priorities of Depot Unloaders and Depot Loaders change randomly.</p><p><span id="source-block-7vahfYQSDvObfe8VQ0z2fe"></span></p><span class="logistics-source-anchor" id="orirock于10月9日晚" aria-hidden="true"></span><h4 id="orirock-evening-of-october-9" tabindex="-1">orirock, Evening of October 9 <a class="header-anchor" href="#orirock-evening-of-october-9" aria-label="Permalink to &quot;orirock, Evening of October 9&quot;">​</a></h4><p>In all four groups, the lower logistics path was placed last. The groups, in order, are: right-hand Depot Loader placed later; a copy of the first group; left-hand Depot Loader placed later; a copy of the third group.</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-cc696542ac133191.q90-6f764f8f967ceb4e.webp" alt="Changes Caused by Going Offline"></p><p>After going offline several times, all four groups remained in the same state.</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-0c56a46ddd414f28.q90-dba10f0f247caaff.webp" alt="Changes Caused by Going Offline"></p><p>Re-placing the right-hand Depot Unloaders in groups two and three caused output lag.</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-b9867200eeb49b55.q90-9d259bbd02f73ade.webp" alt="Changes Caused by Going Offline"></p><p>After one minute offline, the lag disappeared.</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-3845f1a166f9a361.q90-31feaa94ef7f105e.webp" alt="Changes Caused by Going Offline"></p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-41c71f6140013347.q90-d9d43f9ae7e9836c.webp" alt="Changes Caused by Going Offline"></p><p>Re-placed the left-hand Depot Loaders in groups one and four.</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-d55f1061158cfa66.q90-6851c7f17caa2f00.webp" alt="Changes Caused by Going Offline"></p><p>After 1 minute offline, the lag had not returned.</p><p><span id="source-block-CXTU0b23RZUrPaeTiipGDT"></span></p><h4 id="斯改-10-21-12-07-42" tabindex="-1">斯改: 10-21 12:07:42 <a class="header-anchor" href="#斯改-10-21-12-07-42" aria-label="Permalink to &quot;斯改: 10-21 12:07:42&quot;">​</a></h4><p>The advanced trash can also has problems after going offline at rates within 120. Anyone still want to investigate? (</p></div>',1)])])}const h=a(n,[["render",t]]);export{f as __pageData,h as default};
